    if applicant.gender == 'female':
        score += 0.5

    if applicant.recommendation_letters == 'strong':
        score += 1.5
    elif applicant.recommendation_letters == 'medium':
        score += 1

    if applicant.personal_statement == 'high quality':
        score += 1.5
    elif applicant.personal_statement == 'medium quality':
        score += 1

    # More weight is given to candidates who can demonstrate acceptance to pay teachers in public elementary schools 
    # or special education programs
    if applicant.skills.get('acceptance to pay teachers in public elementary schools or special education programs', False):
        score += 1

    # More weight to candidates from first generation and candidates from low income families 
    # and candidates from underrepresented minorities
    background_score = sum([
        applicant.parents_income in ['low', 'very low'] and applicant.parents_degree in ['non-degree', 'bachelor', 'master', 'PhD'],
        applicant.first_generation,
        applicant.race in ['black', 'hispanic', 'native american', 'asian or pacific islander', 'african american']
    ])

    score += background_score * 0.75  # add 0.75 points for each qualifying factor

    if applicant.GPA >= 3.5:
        score += 0.5
    elif applicant.GPA >= 3.0:
        score += 0.3

    return score

