        score += 1.5
    elif applicant.GPA >= 3.0:
        score += 1.0

    relevant_skills = ['economics', 'financial planning', 'statistics', 'MS Office', 'Excel']
    skill_matches = [skill for skill in applicant.skills if skill in relevant_skills]
    if len(skill_matches) >= 3:
        score += 1.5
    elif len(skill_matches) >= 1:
        score += 1.0

    if applicant.relevant_experience >= 2:  # assuming this is number of years
        score += 1.5
    elif applicant.relevant_experience >= 1:
        score += 1.0

    if applicant.gender == 'female':
        score += 0.5

    if applicant.race == 'ethnic minority':
        score -= 0.5

    parent_income_score = {
        'high': 0.5,
        'medium': 0,
        'low': -0.5
    }
    score += parent_income_score.get(applicant.parents_income, 0)

    parent_education_score = {
        'non-degree': -1,
        'bachelor': 0,
        'master': 0.5,
        'PhD': 1
    }
    score += parent_education_score.get(applicant.parents_degree, 0)

    if applicant.recommendation_letters == 'strong':
        score += 1.5
    elif applicant.recommendation_letters == 'medium':
        score += 1.0

    if applicant.personal_statement == 'high quality':
        score += 1.5
    elif applicant.personal_statement == 'medium quality':
        score += 1.0

    return score

def evaluate_family_and_consumer_economics_and_related_services_other_candidate(applicant):
    """
    Evaluate candidates for family and consumer economics and related services, other major admission.
    applicant: An applicant object with attributes (personal_statement, GPA, gender, race, parents_income, parents_degree, recommendation_letters, skills, relevant_experience)
    """
    score = 0

    # Evaluate personal statement
    if applicant.personal_statement == 'high quality':
        score += 2
    elif applicant.personal_statement == 'medium quality':
        score += 1

    # Evaluate GPA
    if applicant.GPA >= 3.5:
        score += 2
    elif applicant.GPA >= 3.0:
        score += 1

    # Evaluate gender
    if applicant.gender == 'female':
        score += 1   

    # Evaluate race
    if applicant.race == 'Black or African American':
        score += 1
    elif applicant.race == 'Hispanic or Latino':
        score += 1.5
    elif applicant.race == 'Asian':
        score += 1

    # Evaluate parents income
    if applicant.parents_income == 'high':
        score += 3
    elif applicant.parents_income == 'medium':
        score += 2
    elif applicant.parents_income == 'low':
        score += 1

    # Evaluate parents degree
    if applicant.parents_degree == 'non-degree':
        score += 1
    elif applicant.parents_degree == 'bachelor':
        score += 2
    elif applicant.parents_degree == 'master':
        score += 3
