        score += 4

    # Evaluate recommendation letters
    if applicant.recommendation_letters == 'strong':
        score += 2
    elif applicant.recommendation_letters == 'medium':
        score += 1

    # Evaluate skills and relevant experience
    score += sum([1 for skill in applicant.skills])  # Assume all skills are relevant and contribute 1
    score += applicant.relevant_experience  # Assume each year of relevant experience contributes 1

